<script setup lang="ts">
import {ref,watch,onMounted,onUnmounted} from 'vue'
import {user,request,explain} from '../services/auth'
import {reconLabel} from '../services/refunds'
import type {ReconciliationSummary,ReconciliationDetail,Page} from '../types/refund'
const data=ref<Page<ReconciliationSummary>>({items:[],page:0,size:20,total:0}),selected=ref<ReconciliationDetail|null>(null),busy=ref(false),error=ref(''),state=ref(''),team=ref(''),alerted=ref(false)
const id=location.pathname.split('/')[3];let sequence=0
async function load(page=data.value.page){if(!user.value||busy.value)return;const seq=sequence,owner=user.value.userId;busy.value=true;error.value='';try{if(id){const v=await request<ReconciliationDetail>('/admin/reconciliations/'+encodeURIComponent(id),owner);if(seq===sequence)selected.value=v}else{const q=new URLSearchParams({page:String(page),size:'20'});if(state.value)q.set('state',state.value);if(team.value.trim())q.set('teamId',team.value.trim());if(alerted.value)q.set('alerted','true');const v=await request<Page<ReconciliationSummary>>('/admin/reconciliations?'+q,owner);if(seq===sequence)data.value=v}}catch(e){if(seq===sequence)error.value=explain(e)}finally{if(seq===sequence)busy.value=false}}
watch(()=>user.value?.userId,()=>{sequence++;busy.value=false;selected.value=null;data.value={items:[],page:0,size:20,total:0};error.value='';void load()});onMounted(()=>void load());onUnmounted(()=>{sequence++})
</script>
<template><section><h1>团队完整核对</h1><button :disabled="busy" @click="load()">刷新</button><p v-if="error" role="alert">{{error}}</p><article v-if="selected"><h2>团队 {{selected.teamId}}</h2><p>{{reconLabel(selected.state)}} · 已准备 {{selected.readyCount}} / {{selected.memberCount}} 个成员</p><p>名单：{{selected.reconciliationId??'待取得'}} · 名单版本 {{selected.rosterVersion??'待取得'}}</p><p>提交：{{selected.completionId??'尚未准备'}} · {{selected.submissionState}}</p><article v-for="m in selected.members" :key="m.outTradeNo"><h3>成员订单 {{m.outTradeNo}}</h3><p>{{reconLabel(m.state)}} · {{m.failureCode??'无异常提示'}}</p><a v-if="m.refundId" :href="'/admin/refunds/'+m.refundId">查看退款进度</a></article><details><summary>关联证据编号</summary><ul><li v-for="e in selected.evidenceIds" :key="e">{{e}}</li></ul></details><a href="/admin/reconciliations">返回核对列表</a></article><template v-else-if="!id"><form @submit.prevent="load(0)"><label>核对进度<select v-model="state"><option value="">全部</option><option v-for="s in ['DISCOVERED','COLLECTING','READY','SUBMITTING','SUBMIT_UNKNOWN','WAITING_DEPENDENCY','RESOLVED','REVIEW_REQUIRED']" :key="s" :value="s">{{reconLabel(s)}}</option></select></label><label>团队编号<input v-model="team" maxlength="64"></label><label><input v-model="alerted" type="checkbox">仅告警</label><button :disabled="busy">筛选</button></form><p v-if="!data.items.length&&!busy">暂无匹配核对任务。</p><article v-for="t in data.items" :key="t.taskId"><h2><a :href="'/admin/reconciliations/'+t.taskId">团队 {{t.teamId}}</a></h2><p>{{reconLabel(t.state)}} · {{t.readyCount}} / {{t.memberCount}} 个成员 {{t.alerted?'· 已告警':''}}</p></article><button :disabled="busy||data.page===0" @click="load(data.page-1)">上一页</button><span>第 {{data.page+1}} 页 · 共 {{data.total}} 条</span><button :disabled="busy||(data.page+1)*data.size>=data.total" @click="load(data.page+1)">下一页</button></template></section></template>
<style scoped>article{overflow-wrap:anywhere}form{display:flex;flex-wrap:wrap;gap:1em}label{display:flex;flex-direction:column}@media(max-width:600px){form{flex-direction:column}h2{font-size:1.1rem}}</style>
